core::DocumentState PictureCard(const core::DocumentState& source,int index,const CardOptions& options,core::composition::Indices& selected){
    core::composition::Validate(source);if(!source.base||index<0||index>=int(source.objects.size())||source.objects.size()>9999||options.padding<0||options.padding>512||options.border<0||options.border>128||options.shadow<0||options.shadow>60||options.color>0xFFFFFF||options.borderColor>0xFFFFFF)throw std::runtime_error("Invalid Picture card options");const auto& original=source.objects[index];core::PictureSource(original);if(original.hidden||original.locked||original.group)throw std::runtime_error("Select one unlocked ungrouped Picture");const CRect frame=original.rect;const int inset=options.padding+options.border,width=frame.Width()+2*inset+options.shadow*2,height=frame.Height()+2*inset+options.shadow*2;if(width<1||height<1||width>32768||height>32768||uint64_t(width)*height*24>512ULL*1024*1024||int64_t(frame.left)+width>32768||int64_t(frame.top)+height>32768)throw std::runtime_error("Picture card size/buffer limit");
    core::Image image;if(!image.Create(width,height))throw std::runtime_error("Card allocation");const int bodyWidth=frame.Width()+2*inset,bodyHeight=frame.Height()+2*inset;for(int y=0;y<height;++y)for(int x=0;x<width;++x){auto* pixel=image.Row(y)+x*4;pixel[0]=pixel[1]=pixel[2]=pixel[3]=0;if(options.shadow){const double offset=options.shadow*.5,dx=std::max({offset-x,0.,x-(bodyWidth+offset-1)}),dy=std::max({offset-y,0.,y-(bodyHeight+offset-1)});pixel[3]=BYTE(std::lround(100*std::clamp(1-std::hypot(dx,dy)/options.shadow,0.,1.)));}if(x<bodyWidth&&y<bodyHeight){const bool edge=x<options.border||y<options.border||x>=bodyWidth-options.border||y>=bodyHeight-options.border;const auto color=edge?options.borderColor:options.color;pixel[0]=GetBValue(color);pixel[1]=GetGValue(color);pixel[2]=GetRValue(color);pixel[3]=255;}}auto result=source;core::Annotation underlay;underlay.tool=core::Tool::Picture;underlay.asset=std::make_shared<core::Image>(std::move(image));underlay.rect={frame.left,frame.top,frame.left+underlay.asset->width,frame.top+underlay.asset->height};result.objects.insert(result.objects.begin()+index,underlay);core::Document::Translate(result.objects[index+1],inset,inset);core::composition::Indices ids{index,index+1};result=core::composition::Group(result,ids,false);const int w=std::max(source.base->width,int(underlay.rect.right)),h=std::max(source.base->height,int(underlay.rect.bottom));if(uint64_t(w)*h*12>512ULL*1024*1024)throw std::runtime_error("Card canvas working limit");if(w!=source.base->width||h!=source.base->height){core::DocumentState expanded;if(!core::ExpandCanvas(result,w,h,expanded))throw std::runtime_error("Cannot expand card canvas");result=std::move(expanded);}selected=std::move(ids);return result;
}
core::Image ToolStylePreview(const ToolStyle& preset,int side){if(!SupportsToolStyle(preset.style.tool)||side<64||side>192)throw std::runtime_error("Invalid style preview");core::Image source;if(!source.Create(240,160))throw std::runtime_error("Preview allocation");for(int y=0;y<160;++y)for(int x=0;x<240;++x){auto* p=source.Row(y)+x*4;const BYTE c=((x/12+y/12)&1)?230:255;p[0]=p[1]=p[2]=c;p[3]=255;}auto a=StyleTemplate(preset.style);a.text=L"Aa 123";a.rect={30,25,210,135};a.fontSize=std::min(a.fontSize,48);a.width=std::min(a.width,16);a.textPadding=std::min(a.textPadding,8);a.points={{40,120},{90,50},{140,95},{200,35}};if(a.tool==core::Tool::Arrow||a.tool==core::Tool::Line)a.points={{35,120},{205,40}};if(a.tool==core::Tool::CurvedArrow)core::StartCurvedArrow(a,{35,120},{205,40});if(a.tool==core::Tool::ElbowArrow)core::StartElbowArrow(a,{35,120},{205,40});if(a.tool==core::Tool::Polygon)core::MakePolygon(a,{35,25},{205,135},5);if(a.tool==core::Tool::Text)a.rect={15,35,230,130};if(a.tool==core::Tool::Step){a.rect={70,30,170,130};a.number=1;}if(a.tool==core::Tool::Stamp)a.text=L"\x2605";if(a.tool==core::Tool::CursorStamp)a.number=0;if(a.tool==core::Tool::Magnifier){a.anchored=true;a.focus={120,80};}if(a.tool==core::Tool::Fill)a.points={{1,1}};if(!RenderObject(source,a))throw std::runtime_error("Cannot render style preview");return core::Resize(source,side,side*2/3);}
